<?php
require __DIR__ . '/103-actionable-summary.php';
$ordinary = $capture;
$run = SSPA_Run_Controller::start(array('type' => 'adhoc', 'url' => $url, 'user_id' => 1, 'all_hooks' => true, 'raw_streams' => true));
if (is_wp_error($run)) throw new RuntimeException($run->get_error_message());
sspa_fleet_complete($run);
$row = $wpdb->get_row($wpdb->prepare('SELECT * FROM %i WHERE run_id = %d ORDER BY id DESC LIMIT 1', SSPA_Schema::table('profiles'), $run), ARRAY_A);
$wrapped = SSPA_Profile_Panel::capture($row);
$raw = isset($wrapped['raw_streams']) ? $wrapped['raw_streams'] : array();
$calls = array_values(array_filter(isset($raw['calls']) ? $raw['calls'] : array(), static function ($call) { return strpos($call['url'], '/summary-slow-endpoint.php') !== false; }));
sspa_fleet_assert(empty($ordinary['raw_streams']['enabled']), 'ordinary signed measurements never replace stream wrappers');
sspa_fleet_assert(!empty($raw['enabled']) && count($calls) === 1 && $calls[0]['ms'] >= 175 && $calls[0]['ms'] < 300 && basename($calls[0]['file']) === 'page.php', 'opt-in pass names the planted raw HTTP read with measured cost and caller');
sspa_fleet_assert($wrapped['boot']['render']['untimed_ms'] < $ordinary['boot']['render']['untimed_ms'] - 140, 'raw stream timing reduces unattributed render time by its planted wait');
$md = SSPA_Markdown_Export::build('page', (int) $row['id']);
$html = SSPA_Profile_Panel::render((int) $row['id']);
sspa_fleet_assert(strpos($md['markdown'], 'summary-slow-endpoint.php') !== false && strpos($md['markdown'], '$http_response_header') !== false && strpos($html, '$http_response_header') !== false && strpos($html, 'summary-slow-endpoint.php') !== false, 'panel and Markdown disclose wrapped streams and changed header scope');
sspa_fleet_assert(strpos($html, 'sspa-time-raw-streams') !== false, 'existing panel offers an explicitly warned raw-stream diagnostic action');
sspa_fleet_assert(empty($wrapped['php_diagnostics']['count']), 'opt-in stream fixture has no PHP diagnostics');
$nested_stream = (new SSPA_Crawler())->profile_job(array('page_key' => 'nested-streams', 'url' => add_query_arg('summary_nested_stream', '1', $url), 'variant' => 'anon', 'flags' => array('ah' => 'all', 'xp' => '0', 'rs' => '1'), 'samples' => 1, 'skip_warmup' => true), 1);
$nested_stream = $nested_stream['samples'][0]['capture'];
$short = array_values(array_filter($nested_stream['boot']['render']['top'], static function ($entry) { return $entry['hook'] === 'shortcode' && $entry['label'] === '[sspa_slow]'; }));
$part = array_values(array_filter($nested_stream['boot']['template_files'], static function ($entry) { return basename($entry['file']) === 'summary-slow.php'; }));
sspa_fleet_assert(count($nested_stream['raw_streams']['calls']) === 3 && count($short) === 1 && $short[0]['ms'] >= 115 && $short[0]['ms'] < 165 && count($part) === 1 && $part[0]['ms'] >= 155 && $part[0]['ms'] < 205, 'nested raw reads are not counted again in shortcode self time or template residuals');
sspa_fleet_assert($calls[0]['bytes'] === strlen('Raw stream wait: 180 ms') && $calls[0]['opened'] && $wrapped['overview']['code'] === 200, 'opt-in stream preserves the fixture response body length and successful request');
sspa_fleet_assert(strpos(wp_json_encode($nested_stream['raw_streams']), 'fixture-only') === false && empty($nested_stream['php_diagnostics']['count']), 'stream URL evidence removes query values without PHP diagnostics');
file_put_contents($out . 'streams-nested.json', wp_json_encode($nested_stream, JSON_PRETTY_PRINT));
file_put_contents($out . 'streams-final.json', wp_json_encode(array('ordinary' => $ordinary, 'wrapped' => $wrapped), JSON_PRETTY_PRINT));
file_put_contents($out . 'streams-final.md', $md['markdown']);
sspa_fleet_done();
